if (!function_exists('app_locale')) {
    function app_locale(): string
    {
        $locale = (string) (service('session')->get('locale') ?? 'en');
        return in_array($locale, ['en', 'hi', 'hinglish'], true) ? $locale : 'en';
    }
}

